"use client";

import { type ComponentProps, useEffect, useRef } from "react";

import { cn } from "@/lib/utils";

export interface AsciiWordmarkProps
	extends Omit<ComponentProps<"div">, "children"> {
	/** Word sampled into the particle field. */
	word?: string;
	/** Base color used by the ASCII glyph ramp. */
	inkColor?: string;
}

export function AsciiWordmark({
	word = "VAULT",
	inkColor = "#8278ff",
	className,
	"aria-label": ariaLabel,
	...props
}: AsciiWordmarkProps) {
	const hostRef = useRef<HTMLDivElement>(null);

	useEffect(() => {
		const hostElement = hostRef.current;
		if (!hostElement) return;

		let disposed = false;
		let instance: {
			dispose: () => void;
			mount: () => boolean;
			start: () => void;
		} | null = null;

		async function mount(target: HTMLDivElement) {
			try {
				const { AsciiWordmarkRenderer } = await import("./renderer");
				if (disposed) return;

				instance = new AsciiWordmarkRenderer(target, { word, inkColor });
				if (instance.mount()) {
					instance.start();
				} else {
					instance.dispose();
					target.dataset.webgl = "unsupported";
				}
			} catch {
				instance?.dispose();
				target.dataset.webgl = "unsupported";
			}
		}

		void mount(hostElement);

		return () => {
			disposed = true;
			instance?.dispose();
		};
	}, [inkColor, word]);

	return (
		<div
			{...props}
			aria-label={ariaLabel ?? `${word} ASCII particle wordmark`}
			className={cn(
				"relative isolate block aspect-[16/5] min-h-48 w-full overflow-hidden",
				className,
			)}
			data-slot="ascii-wordmark"
			ref={hostRef}
			role="img"
		/>
	);
}

export default AsciiWordmark;

import * as THREE from "three";
import { GPUComputationRenderer } from "three/examples/jsm/misc/GPUComputationRenderer.js";
import { EffectComposer } from "three/examples/jsm/postprocessing/EffectComposer.js";
import { RenderPass } from "three/examples/jsm/postprocessing/RenderPass.js";
import { ShaderPass } from "three/examples/jsm/postprocessing/ShaderPass.js";

import { buildAtlas, RAMP } from "./atlas";
import {
	ASCII_FRAG,
	ASCII_VERT,
	GPGPU_COMPUTE,
	PARTICLE_FRAG,
	PARTICLE_VERT,
	TRAIL_LEN,
} from "./shaders";
import { buildWordPoints } from "./word-points";

const FLOW_INFLUENCE = 0.43;
const FLOW_STRENGTH = 1.09;
const FLOW_FREQUENCY = 0.53;
const MOUSE_STRENGTH = 0.08;
const MOUSE_SPEED_GAIN = 1.5;
const RENDER_SCALE = 0.5;
const ASCII_CELL_DIVISOR = 100;

export interface AsciiWordmarkOptions {
	word: string;
	inkColor: string;
}

export class AsciiWordmarkRenderer {
	private readonly host: HTMLElement;
	private readonly options: AsciiWordmarkOptions;
	private readonly isTouch: boolean;
	private readonly reducedMotion: boolean;
	private readonly fboSize: number;
	private readonly maxDpr: number;

	private renderer!: THREE.WebGLRenderer;
	private readonly scene = new THREE.Scene();
	private camera!: THREE.PerspectiveCamera;
	private composer!: EffectComposer;
	private asciiPass!: ShaderPass;
	private gpgpu!: GPUComputationRenderer;
	private posVar!: ReturnType<GPUComputationRenderer["addVariable"]>;
	private points!: THREE.Points;
	private pointsMat!: THREE.ShaderMaterial;

	private readonly clock = new THREE.Clock();
	private raf = 0;
	private running = false;
	private onScreen = true;
	private disposed = false;

	private readonly mouse = new THREE.Vector3(9999, 9999, 0);
	private readonly prevMouse = new THREE.Vector3(9999, 9999, 0);
	private mouseSpeed = 0;
	private readonly mouseUv = new THREE.Vector2(9999, 9999);
	private onCard = false;

	private trailPos: THREE.Vector2[] = [];
	private trailAge = new Float32Array(TRAIL_LEN).fill(1);
	private trailOn = 0;
	private visibility = 0;
	private wordAspect = 3;
	private readonly wordMargin = 0.92;
	private readonly cleanupFns: (() => void)[] = [];
	private intersectionObserver?: IntersectionObserver;
	private resizeObserver?: ResizeObserver;

	constructor(host: HTMLElement, options: AsciiWordmarkOptions) {
		this.host = host;
		this.options = options;
		this.isTouch = window.matchMedia?.("(pointer: coarse)").matches ?? false;
		this.reducedMotion =
			window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false;
		this.fboSize = this.isTouch ? 128 : 200;
		this.maxDpr = this.isTouch ? 1.5 : 2;
	}

	mount(): boolean {
		const { clientWidth: width, clientHeight: height } = this.host;
		if (width === 0 || height === 0) return false;

		const dpr = Math.min(window.devicePixelRatio || 1, this.maxDpr);
		this.renderer = new THREE.WebGLRenderer({
			alpha: true,
			antialias: false,
			powerPreference: "high-performance",
			failIfMajorPerformanceCaveat: false,
		});
		this.renderer.setPixelRatio(dpr);
		this.renderer.setSize(width, height);
		this.renderer.setClearColor(0x000000, 0);
		this.renderer.domElement.setAttribute("aria-hidden", "true");
		Object.assign(this.renderer.domElement.style, {
			position: "absolute",
			inset: "0",
			width: "100%",
			height: "100%",
			display: "block",
			touchAction: "pan-y",
			userSelect: "none",
			WebkitUserSelect: "none",
		});
		this.host.appendChild(this.renderer.domElement);

		const { positions, count, aspect } = buildWordPoints(
			this.options.word,
			this.fboSize,
		);
		this.wordAspect = aspect;
		this.camera = new THREE.PerspectiveCamera(35, width / height, 0.1, 100);
		this.frameWord(width / height);
		this.camera.lookAt(0, 0, 0);

		if (!this.initGpgpu(positions)) return false;
		this.initPoints(count);
		this.initComposer(width, height, dpr);
		this.bindEvents();
		return true;
	}

	private initGpgpu(positions: Float32Array): boolean {
		this.gpgpu = new GPUComputationRenderer(
			this.fboSize,
			this.fboSize,
			this.renderer,
		);
		this.gpgpu.setDataType(THREE.HalfFloatType);

		const baseTexture = this.gpgpu.createTexture();
		(baseTexture.image.data as Float32Array).set(positions);
		const initialTexture = this.gpgpu.createTexture();
		(initialTexture.image.data as Float32Array).set(positions);

		this.posVar = this.gpgpu.addVariable(
			"uParticles",
			GPGPU_COMPUTE,
			initialTexture,
		);
		this.gpgpu.setVariableDependencies(this.posVar, [this.posVar]);

		const uniforms = this.posVar.material.uniforms;
		uniforms.uTime = { value: 0 };
		uniforms.uDeltaTime = { value: 0 };
		uniforms.uBase = { value: baseTexture };
		uniforms.uFlowFieldInfluence = { value: FLOW_INFLUENCE };
		uniforms.uFlowFieldStrength = { value: FLOW_STRENGTH };
		uniforms.uFlowFieldFrequency = { value: FLOW_FREQUENCY };
		uniforms.uMouse = { value: new THREE.Vector3(9999, 9999, 0) };
		uniforms.uMouseStrength = { value: MOUSE_STRENGTH };
		uniforms.uMouseSpeed = { value: 0 };

		const error = this.gpgpu.init();
		if (error) {
			console.warn("[ascii-wordmark] GPGPU unsupported, skipping:", error);
			return false;
		}
		return true;
	}

	private initPoints(count: number) {
		const geometry = new THREE.BufferGeometry();
		const uvs = new Float32Array(count * 2);
		const sizes = new Float32Array(count);
		let index = 0;

		for (let y = 0; y < this.fboSize; y++) {
			for (let x = 0; x < this.fboSize; x++) {
				uvs[index * 2] = (x + 0.5) / this.fboSize;
				uvs[index * 2 + 1] = (y + 0.5) / this.fboSize;
				sizes[index] = 0.6 + Math.random() * 0.8;
				index++;
			}
		}

		geometry.setAttribute(
			"position",
			new THREE.BufferAttribute(new Float32Array(count * 3), 3),
		);
		geometry.setAttribute("aParticlesUv", new THREE.BufferAttribute(uvs, 2));
		geometry.setAttribute("aSize", new THREE.BufferAttribute(sizes, 1));
		geometry.setDrawRange(0, count);

		this.pointsMat = new THREE.ShaderMaterial({
			vertexShader: PARTICLE_VERT,
			fragmentShader: PARTICLE_FRAG,
			transparent: true,
			depthWrite: false,
			blending: THREE.AdditiveBlending,
			uniforms: {
				uResolution: { value: new THREE.Vector2() },
				uSize: { value: 4 },
				uVisibility: { value: 0 },
				uParticlesTexture: { value: null },
			},
		});

		this.points = new THREE.Points(geometry, this.pointsMat);
		this.points.frustumCulled = false;
		this.scene.add(this.points);
	}

	private initComposer(width: number, height: number, dpr: number) {
		const bufferWidth = Math.max(2, Math.round(width * RENDER_SCALE));
		const bufferHeight = Math.max(2, Math.round(height * RENDER_SCALE));

		this.composer = new EffectComposer(this.renderer);
		this.composer.setPixelRatio(dpr);
		this.composer.setSize(width, height);
		this.composer.addPass(new RenderPass(this.scene, this.camera));

		const atlasTexture = new THREE.CanvasTexture(buildAtlas(RAMP));
		atlasTexture.minFilter = THREE.LinearFilter;
		atlasTexture.magFilter = THREE.LinearFilter;
		const ink = new THREE.Color(this.options.inkColor);

		this.trailPos = Array.from(
			{ length: TRAIL_LEN },
			() => new THREE.Vector2(9999, 9999),
		);
		this.trailAge = new Float32Array(TRAIL_LEN).fill(1);
		this.asciiPass = new ShaderPass({
			uniforms: {
				tDiffuse: { value: null },
				uResolution: {
					value: new THREE.Vector2(bufferWidth * dpr, bufferHeight * dpr),
				},
				uAsciiPixelSize: {
					value: (bufferWidth * dpr) / ASCII_CELL_DIVISOR,
				},
				uAsciiTexture: { value: atlasTexture },
				uCharCount: { value: new THREE.Vector2(RAMP.length, 1) },
				uAsciiContrast: { value: 1.4 },
				uAsciiBrightness: { value: 0.12 },
				uAsciiMin: { value: 0 },
				uAsciiMax: { value: 1 },
				uAspect: { value: width / height },
				uInk: { value: new THREE.Vector3(ink.r, ink.g, ink.b) },
				uTrail: { value: this.trailPos },
				uTrailAge: { value: this.trailAge },
				uTrailOn: { value: 0 },
			},
			vertexShader: ASCII_VERT,
			fragmentShader: ASCII_FRAG,
		});
		this.asciiPass.renderToScreen = true;
		this.composer.addPass(this.asciiPass);
		this.pointsMat.uniforms.uResolution.value.set(width * dpr, height * dpr);
	}

	private bindEvents() {
		if (!this.reducedMotion) {
			const onPointerMove = (event: PointerEvent) => {
				if (event.pointerType === "touch") return;
				const bounds = this.host.getBoundingClientRect();
				const normalizedX =
					((event.clientX - bounds.left) / bounds.width) * 2 - 1;
				const normalizedY = -(
					((event.clientY - bounds.top) / bounds.height) * 2 -
					1
				);
				const projected = new THREE.Vector3(
					normalizedX,
					normalizedY,
					0.5,
				).unproject(this.camera);
				const direction = projected.sub(this.camera.position).normalize();
				const distance = -this.camera.position.z / direction.z;
				this.mouse
					.copy(this.camera.position)
					.add(direction.multiplyScalar(distance));
				this.mouseUv.set(
					(event.clientX - bounds.left) / bounds.width,
					1 - (event.clientY - bounds.top) / bounds.height,
				);
				this.onCard = true;
			};
			const onPointerLeave = () => {
				this.mouse.set(9999, 9999, 0);
				this.mouseUv.set(9999, 9999);
				this.onCard = false;
			};

			this.host.addEventListener("pointermove", onPointerMove);
			this.host.addEventListener("pointerleave", onPointerLeave);
			this.cleanupFns.push(() => {
				this.host.removeEventListener("pointermove", onPointerMove);
				this.host.removeEventListener("pointerleave", onPointerLeave);
			});
		}

		const onVisibilityChange = () =>
			document.hidden ? this.stop() : this.maybeStart();
		document.addEventListener("visibilitychange", onVisibilityChange);
		this.cleanupFns.push(() =>
			document.removeEventListener("visibilitychange", onVisibilityChange),
		);

		this.intersectionObserver = new IntersectionObserver(
			(entries) => {
				this.onScreen = entries[0]?.isIntersecting ?? true;
				this.onScreen ? this.maybeStart() : this.stop();
			},
			{ threshold: 0.01 },
		);
		this.intersectionObserver.observe(this.host);

		this.resizeObserver = new ResizeObserver(() => this.resize());
		this.resizeObserver.observe(this.host);
	}

	private frameWord(viewportAspect: number) {
		const halfVerticalFov = THREE.MathUtils.degToRad(this.camera.fov) / 2;
		const verticalTangent = Math.tan(halfVerticalFov);
		const distanceForHeight = 1 / verticalTangent;
		const distanceForWidth =
			this.wordAspect / (verticalTangent * viewportAspect);
		const distance =
			Math.max(distanceForHeight, distanceForWidth) * this.wordMargin;
		this.camera.position.set(0, 0, distance);
	}

	private resize() {
		if (this.disposed) return;
		const { clientWidth: width, clientHeight: height } = this.host;
		if (width === 0 || height === 0) return;

		const dpr = Math.min(window.devicePixelRatio || 1, this.maxDpr);
		this.renderer.setPixelRatio(dpr);
		this.renderer.setSize(width, height);
		this.composer.setPixelRatio(dpr);
		this.composer.setSize(width, height);
		this.camera.aspect = width / height;
		this.frameWord(width / height);
		this.camera.updateProjectionMatrix();

		const bufferWidth = Math.max(2, Math.round(width * RENDER_SCALE));
		const bufferHeight = Math.max(2, Math.round(height * RENDER_SCALE));
		this.asciiPass.uniforms.uResolution.value.set(
			bufferWidth * dpr,
			bufferHeight * dpr,
		);
		this.asciiPass.uniforms.uAsciiPixelSize.value =
			(bufferWidth * dpr) / ASCII_CELL_DIVISOR;
		this.asciiPass.uniforms.uAspect.value = width / height;
		this.pointsMat.uniforms.uResolution.value.set(width * dpr, height * dpr);

		if (this.reducedMotion) this.renderStatic();
	}

	start() {
		this.onScreen = true;
		this.maybeStart();
	}

	private maybeStart() {
		if (this.disposed || !this.onScreen || document.hidden) return;
		if (this.reducedMotion) {
			this.renderStatic();
			return;
		}
		if (this.running) return;

		this.running = true;
		this.clock.getDelta();
		this.raf = requestAnimationFrame(this.loop);
	}

	stop() {
		this.running = false;
		if (this.raf) cancelAnimationFrame(this.raf);
		this.raf = 0;
	}

	private renderStatic() {
		if (this.disposed || !this.composer) return;
		const uniforms = this.posVar.material.uniforms;
		uniforms.uDeltaTime.value = 0;
		this.gpgpu.compute();
		this.pointsMat.uniforms.uParticlesTexture.value =
			this.gpgpu.getCurrentRenderTarget(this.posVar).texture;
		this.pointsMat.uniforms.uVisibility.value = 1;
		this.asciiPass.uniforms.uTrailOn.value = 0;
		this.composer.render();
	}

	private advanceTrail(deltaTime: number) {
		const trailLife = 0.75;
		for (let index = 0; index < TRAIL_LEN; index++) {
			this.trailAge[index] = Math.min(
				1,
				(this.trailAge[index] ?? 1) + deltaTime / trailLife,
			);
		}

		if (this.onCard) {
			for (let index = TRAIL_LEN - 1; index > 0; index--) {
				this.trailPos[index]?.copy(this.trailPos[index - 1] ?? this.mouseUv);
				this.trailAge[index] = this.trailAge[index - 1] ?? 1;
			}
			this.trailPos[0]?.copy(this.mouseUv);
			this.trailAge[0] = 0;
		}
		this.asciiPass.uniforms.uTrailAge.value = this.trailAge;
	}

	private readonly loop = () => {
		if (!this.running) return;

		const deltaTime = Math.min(this.clock.getDelta(), 1 / 30);
		const elapsedTime = this.clock.elapsedTime;
		this.mouseSpeed = this.mouse.distanceTo(this.prevMouse);
		if (this.mouse.x > 9000) this.mouseSpeed = 0;
		this.prevMouse.copy(this.mouse);

		const computeUniforms = this.posVar.material.uniforms;
		computeUniforms.uTime.value = elapsedTime;
		computeUniforms.uDeltaTime.value = deltaTime;
		computeUniforms.uMouse.value.copy(this.mouse);
		computeUniforms.uMouseSpeed.value = this.mouseSpeed * MOUSE_SPEED_GAIN;
		this.gpgpu.compute();

		this.pointsMat.uniforms.uParticlesTexture.value =
			this.gpgpu.getCurrentRenderTarget(this.posVar).texture;
		this.visibility = Math.min(1, this.visibility + deltaTime * 0.9);
		this.pointsMat.uniforms.uVisibility.value = this.visibility;

		this.advanceTrail(deltaTime);
		this.trailOn +=
			((this.onCard ? 1 : 0) - this.trailOn) * Math.min(1, deltaTime * 6);
		this.asciiPass.uniforms.uTrailOn.value = this.trailOn;
		this.composer.render();
		this.raf = requestAnimationFrame(this.loop);
	};

	dispose() {
		if (this.disposed) return;
		this.disposed = true;
		this.stop();
		for (const cleanup of this.cleanupFns) cleanup();
		this.intersectionObserver?.disconnect();
		this.resizeObserver?.disconnect();
		this.points?.geometry.dispose();
		this.pointsMat?.dispose();
		this.asciiPass?.uniforms.uAsciiTexture.value?.dispose?.();
		this.gpgpu?.dispose();
		this.composer?.dispose();
		this.renderer?.dispose();
		this.renderer?.forceContextLoss();
		this.renderer?.domElement.remove();
	}
}

export const GPGPU_COMPUTE = `
uniform float uTime;
uniform float uDeltaTime;
uniform float uFlowFieldInfluence;
uniform float uFlowFieldStrength;
uniform float uFlowFieldFrequency;

uniform vec3 uMouse;
uniform float uMouseStrength;
uniform float uMouseSpeed;

uniform sampler2D uBase;

vec4 permute(vec4 x){return mod(((x*34.0)+1.0)*x, 289.0);}
float permute(float x){return floor(mod(((x*34.0)+1.0)*x, 289.0));}
vec4 taylorInvSqrt(vec4 r){return 1.79284291400159 - 0.85373472095314 * r;}
float taylorInvSqrt(float r){return 1.79284291400159 - 0.85373472095314 * r;}

vec4 grad4(float j, vec4 ip){
  const vec4 ones = vec4(1.0, 1.0, 1.0, -1.0);
  vec4 p,s;
  p.xyz = floor(fract(vec3(j) * ip.xyz) * 7.0) * ip.z - 1.0;
  p.w = 1.5 - dot(abs(p.xyz), ones.xyz);
  s = vec4(lessThan(p, vec4(0.0)));
  p.xyz = p.xyz + (s.xyz*2.0 - 1.0) * s.www;
  return p;
}

float simplexNoise4d(vec4 v){
  const vec2 C = vec2(0.138196601125010504, 0.309016994374947451);
  vec4 i = floor(v + dot(v, C.yyyy));
  vec4 x0 = v - i + dot(i, C.xxxx);
  vec4 i0;
  vec3 isX = step(x0.yzw, x0.xxx);
  vec3 isYZ = step(x0.zww, x0.yyz);
  i0.x = isX.x + isX.y + isX.z;
  i0.yzw = 1.0 - isX;
  i0.y += isYZ.x + isYZ.y;
  i0.zw += 1.0 - isYZ.xy;
  i0.z += isYZ.z;
  i0.w += 1.0 - isYZ.z;
  vec4 i3 = clamp(i0, 0.0, 1.0);
  vec4 i2 = clamp(i0-1.0, 0.0, 1.0);
  vec4 i1 = clamp(i0-2.0, 0.0, 1.0);
  vec4 x1 = x0 - i1 + C.xxxx;
  vec4 x2 = x0 - i2 + 2.0 * C.xxxx;
  vec4 x3 = x0 - i3 + 3.0 * C.xxxx;
  vec4 x4 = x0 - 1.0 + 4.0 * C.xxxx;
  i = mod(i, 289.0);
  float j0 = permute(permute(permute(permute(i.w) + i.z) + i.y) + i.x);
  vec4 j1 = permute(permute(permute(permute(
    i.w + vec4(i1.w, i2.w, i3.w, 1.0))
    + i.z + vec4(i1.z, i2.z, i3.z, 1.0))
    + i.y + vec4(i1.y, i2.y, i3.y, 1.0))
    + i.x + vec4(i1.x, i2.x, i3.x, 1.0));
  vec4 ip = vec4(1.0/294.0, 1.0/49.0, 1.0/7.0, 0.0);
  vec4 p0 = grad4(j0, ip);
  vec4 p1 = grad4(j1.x, ip);
  vec4 p2 = grad4(j1.y, ip);
  vec4 p3 = grad4(j1.z, ip);
  vec4 p4 = grad4(j1.w, ip);
  vec4 norm = taylorInvSqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2,p2), dot(p3,p3)));
  p0 *= norm.x; p1 *= norm.y; p2 *= norm.z; p3 *= norm.w;
  p4 *= taylorInvSqrt(dot(p4,p4));
  vec3 m0 = max(0.6 - vec3(dot(x0,x0), dot(x1,x1), dot(x2,x2)), 0.0);
  vec2 m1 = max(0.6 - vec2(dot(x3,x3), dot(x4,x4)), 0.0);
  m0 *= m0;
  m1 *= m1;
  return 49.0 * (dot(m0*m0, vec3(dot(p0,x0), dot(p1,x1), dot(p2,x2)))
    + dot(m1*m1, vec2(dot(p3,x3), dot(p4,x4))));
}

void main() {
  float time = uTime * 0.2;
  vec2 uv = gl_FragCoord.xy / resolution.xy;
  vec4 particle = texture2D(uParticles, uv);
  vec4 base = texture2D(uBase, uv);

  float repelStrength = clamp(uMouseSpeed, 0.0, uMouseStrength);
  vec3 mouseDelta = particle.xyz - uMouse;
  float dist = max(length(mouseDelta), 0.001);
  vec3 dir = mouseDelta / dist;
  float repulsionForce = repelStrength / (dist * (dist + 1.0));
  particle.xyz += dir * repulsionForce * 2.0 * repelStrength;

  if (particle.a >= 1.0) {
    particle.a = mod(particle.a, 1.0);
    particle.xyz = base.xyz;
  } else {
    float strength = simplexNoise4d(vec4(base.xyz, time + 1.0));
    float influence = (uFlowFieldInfluence - 0.5) * -2.0;
    strength = smoothstep(influence, 1.0, strength);

    vec3 flowField = vec3(
      simplexNoise4d(vec4(particle.xyz * uFlowFieldFrequency, time)),
      simplexNoise4d(vec4(particle.xyz * uFlowFieldFrequency + 1.0, time)),
      simplexNoise4d(vec4(particle.xyz * uFlowFieldFrequency + 2.0, time))
    );
    particle.xyz += normalize(flowField) * uDeltaTime * strength * uFlowFieldStrength;
    particle.a += uDeltaTime * 0.3;
    particle.xyz += (base.xyz - particle.xyz) * uDeltaTime * 2.2;
  }

  gl_FragColor = particle;
}
`;

export const PARTICLE_VERT = `
uniform vec2 uResolution;
uniform float uSize;
uniform float uVisibility;
uniform sampler2D uParticlesTexture;

attribute vec2 aParticlesUv;
attribute float aSize;

varying float vAlpha;

void main() {
  vec4 particle = texture2D(uParticlesTexture, aParticlesUv);
  vec4 modelPosition = modelMatrix * vec4(particle.xyz, 1.0);
  vec4 viewPosition = viewMatrix * modelPosition;
  gl_Position = projectionMatrix * viewPosition;
  vAlpha = uVisibility;
  gl_PointSize = uSize * aSize * uResolution.y * 0.006;
  gl_PointSize *= 1.0 / -viewPosition.z;
}
`;

export const PARTICLE_FRAG = `
varying float vAlpha;

void main() {
  vec2 center = gl_PointCoord - 0.5;
  float distanceFromCenter = length(center);
  if (distanceFromCenter > 0.5) discard;
  float alpha = smoothstep(0.5, 0.15, distanceFromCenter) * vAlpha;
  gl_FragColor = vec4(vec3(1.0), alpha);
}
`;

export const ASCII_VERT = `
varying vec2 vUv;

void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}
`;

export const TRAIL_LEN = 24;

export const ASCII_FRAG = `
uniform sampler2D tDiffuse;
uniform vec2 uResolution;
uniform float uAsciiPixelSize;
uniform sampler2D uAsciiTexture;
uniform vec2 uCharCount;
uniform float uAsciiContrast;
uniform float uAsciiBrightness;
uniform float uAsciiMin;
uniform float uAsciiMax;

uniform float uAspect;
uniform vec3 uInk;
uniform vec2 uTrail[${TRAIL_LEN}];
uniform float uTrailAge[${TRAIL_LEN}];
uniform float uTrailOn;

varying vec2 vUv;

void main() {
  vec2 normalizedPixelSize = vec2(uAsciiPixelSize) / uResolution;
  vec2 uvPixel = normalizedPixelSize * floor(vUv / normalizedPixelSize);
  vec4 texColor = texture2D(tDiffuse, uvPixel);

  float lumaRGB = dot(vec3(0.2126, 0.7152, 0.0722), texColor.rgb);
  float luma = max(lumaRGB, texColor.a);
  luma = (luma - uAsciiMin) / (uAsciiMax - uAsciiMin);
  luma = clamp(luma + uAsciiBrightness, 0.0, 1.0);
  luma = clamp((luma - 0.5) * uAsciiContrast + 0.5, 0.0, 1.0);

  vec2 cellUV = fract(vUv / normalizedPixelSize);
  float charIndex = clamp(floor(luma * (uCharCount.x - 1.0)), 0.0, uCharCount.x - 1.0);
  vec2 asciiUV = vec2((charIndex + cellUV.x) / uCharCount.x, cellUV.y);
  float character = texture2D(uAsciiTexture, asciiUV).r;
  vec2 cellCenter = uvPixel + normalizedPixelSize * 0.5;

  vec3 inkDeep = uInk * 0.58;
  vec3 inkLift = min(vec3(1.0), uInk * 1.08);
  vec3 baseColor = mix(inkDeep, inkLift, smoothstep(0.0, 1.0, cellCenter.x));

  float trail = 0.0;
  float headness = 0.0;
  for (int i = 0; i < ${TRAIL_LEN}; i++) {
    float age = uTrailAge[i];
    if (age >= 1.0) continue;
    vec2 delta = (cellCenter - uTrail[i]) * vec2(uAspect, 1.0);
    float radius = 0.16 + age * 0.10;
    float glow = smoothstep(radius, 0.0, length(delta)) * (1.0 - age);
    if (glow > trail) {
      trail = glow;
      headness = 1.0 - age;
    }
  }
  trail *= uTrailOn;

  vec3 trailCool = vec3(0.29, 0.23, 1.0);
  vec3 trailHot = vec3(1.0, 0.32, 0.68);
  vec3 trailColor = mix(trailCool, trailHot, headness);
  vec3 glyphColor = mix(baseColor, trailColor, clamp(trail, 0.0, 1.0));

  float ink = character * smoothstep(0.015, 0.18, luma);
  ink = min(1.0, ink + trail * character * 0.3);
  gl_FragColor = vec4(glyphColor * ink, ink);
}
`;

export const RAMP = " .:-=+*#%VAULT";

export function buildAtlas(ramp = RAMP, cell = 64): HTMLCanvasElement {
	const canvas = document.createElement("canvas");
	canvas.width = cell * ramp.length;
	canvas.height = cell;

	const context = canvas.getContext("2d");
	if (!context) throw new Error("Unable to create the ASCII atlas canvas.");

	context.clearRect(0, 0, canvas.width, canvas.height);
	context.fillStyle = "#fff";
	context.textAlign = "center";
	context.textBaseline = "middle";
	context.font = `${Math.floor(cell * 0.74)}px ui-monospace, "SF Mono", Menlo, monospace`;

	for (let index = 0; index < ramp.length; index++) {
		const character = ramp[index];
		if (character && character !== " ") {
			context.fillText(
				character,
				index * cell + cell / 2,
				cell / 2 + cell * 0.04,
			);
		}
	}

	return canvas;
}

export interface WordPoints {
	positions: Float32Array;
	count: number;
	aspect: number;
}

export function buildWordPoints(word: string, size: number): WordPoints {
	const count = size * size;
	const width = 1024;
	const height = 320;
	const canvas = document.createElement("canvas");
	canvas.width = width;
	canvas.height = height;

	const context = canvas.getContext("2d", { willReadFrequently: true });
	if (!context) throw new Error("Unable to create the word sampling canvas.");

	context.clearRect(0, 0, width, height);
	context.fillStyle = "#fff";
	context.textAlign = "center";
	context.textBaseline = "middle";

	let fontSize = 240;
	context.font = `800 ${fontSize}px ui-sans-serif, system-ui, sans-serif`;
	const margin = 80;
	const measured = context.measureText(word).width;
	if (measured > width - margin) {
		fontSize = Math.floor(fontSize * ((width - margin) / measured));
		context.font = `800 ${fontSize}px ui-sans-serif, system-ui, sans-serif`;
	}
	context.fillText(word, width / 2, height / 2);

	const data = context.getImageData(0, 0, width, height).data;
	const lit: [number, number][] = [];
	const stride = 2;

	for (let y = 0; y < height; y += stride) {
		for (let x = 0; x < width; x += stride) {
			const alpha = data[(y * width + x) * 4 + 3];
			if (alpha && alpha > 128) lit.push([x, y]);
		}
	}

	if (lit.length === 0) {
		for (let index = 0; index < 256; index++) {
			lit.push([width / 2, height / 2]);
		}
	}

	const aspect = width / height;
	const positions = new Float32Array(count * 4);
	for (let index = 0; index < count; index++) {
		const point = lit[(Math.random() * lit.length) | 0] ?? [
			width / 2,
			height / 2,
		];
		const jitterX = (Math.random() - 0.5) * stride;
		const jitterY = (Math.random() - 0.5) * stride;
		const normalizedX = ((point[0] + jitterX) / width - 0.5) * 2 * aspect;
		const normalizedY = -((point[1] + jitterY) / height - 0.5) * 2;

		positions[index * 4] = normalizedX;
		positions[index * 4 + 1] = normalizedY;
		positions[index * 4 + 2] = (Math.random() - 0.5) * 0.08;
		positions[index * 4 + 3] = Math.random();
	}

	return { positions, count, aspect };
}
